-- Create Database
CREATE DATABASE IF NOT EXISTS order_management_system;
USE order_management_system;

-- 1. Store Table
-- Represents physical or digital outlets
CREATE TABLE stores (
    store_id UUID PRIMARY KEY DEFAULT UUID(),
    name VARCHAR(255) NOT NULL,
    is_deleted BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

-- 2. Product Table
-- Contains item details linked to a specific store via store_id
CREATE TABLE products (
    product_id UUID PRIMARY KEY DEFAULT UUID(),
    store_id UUID NOT NULL,
    name VARCHAR(255) NOT NULL,
    description VARCHAR(255),
    price DECIMAL(19, 4) NOT NULL,
    stock INT DEFAULT 0,
    is_deleted BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_product_store FOREIGN KEY (store_id) REFERENCES stores(store_id)
);

-- 3. Customer Table
-- Stores user profiles and geographic location data
CREATE TABLE customers (
    customer_id UUID PRIMARY KEY DEFAULT UUID(),
    name VARCHAR(255) NOT NULL,
    city VARCHAR(255),
    province VARCHAR(255),
    is_deleted BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

-- 4. Order Table
-- Header record for a transaction linked to a specific customer
CREATE TABLE orders (
    order_id UUID PRIMARY KEY DEFAULT UUID(),
    customer_id UUID NOT NULL,
    status VARCHAR(255) NOT NULL DEFAULT 'Pending',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_order_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

-- 5. OrderProduct Table
-- Junction table capturing the snapshot of price and quantity at time of purchase
CREATE TABLE order_products (
    order_id UUID NOT NULL,
    product_id UUID NOT NULL,
    quantity INT NOT NULL,
    price_at_checkout DECIMAL(19, 4) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (order_id, product_id),
    CONSTRAINT fk_op_order FOREIGN KEY (order_id) REFERENCES orders(order_id),
    CONSTRAINT fk_op_product FOREIGN KEY (product_id) REFERENCES products(product_id)
);

USE order_management_system;





